package com.focusflow.api.controller; import com.focusflow.api.dto.ApiDtos.*; import com.focusflow.api.service.SyncService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/sync") public class SyncController {final SyncService service;public SyncController(SyncService s){service=s;}@GetMapping SyncResponse load(Authentication a){return service.load((String)a.getPrincipal());}@PostMapping SyncResponse save(@RequestBody SyncRequest r,Authentication a){return service.save(r,(String)a.getPrincipal());} }
